using System.Reflection;
using System.Runtime.Loader;
using Intropy.Topology;

namespace Intropy.Topology.Generation.Test;

/// <summary>
/// Loads a compiled work-in-progress system — placeholder transport, one-sided topic —
/// into an isolated <see cref="AssemblyLoadContext"/> so its <see cref="ISystemDefinition"/>
/// stays invisible to the tests using this assembly's own definition.
/// </summary>
internal static class WipSystem
{
    private const string Source = """
        using Intropy.Topology;

        public sealed record WipOrder(string OrderNumber);

        public sealed class WipSystem : ISystemDefinition
        {
            public static readonly TopicRef<WipOrder> Raw = TopicRef<WipOrder>.Define("pubsub-a", "wip-raw");
            public static readonly ConnectorRef Placeholder = ConnectorRef.Define("placeholder", Transport.Default());

            public string SystemName => "wip-system";

            public void Define(SystemBuilder builder)
            {
                builder.AddExtractor("wip-extractor").From(Placeholder).Publishes(Raw);
            }
        }

        public sealed class WipDevelopment : IDevelopmentDefinition
        {
            public void Define(DevelopmentBuilder development)
            {
                development.Files(WipSystem.Placeholder).RootPath("./test/placeholder");
            }
        }
        """;

    public static Assembly Load()
    {
        var topologyAssembly = typeof(ISystemDefinition).Assembly.Location;
        var syntaxTree = Microsoft.CodeAnalysis.CSharp.CSharpSyntaxTree.ParseText(Source);
        var compilation = Microsoft.CodeAnalysis.CSharp.CSharpCompilation.Create(
            "Intropy.Topology.WipTestSystem",
            [syntaxTree],
            [Microsoft.CodeAnalysis.MetadataReference.CreateFromFile(typeof(object).Assembly.Location),
             Microsoft.CodeAnalysis.MetadataReference.CreateFromFile(topologyAssembly)],
            new Microsoft.CodeAnalysis.CSharp.CSharpCompilationOptions(
                Microsoft.CodeAnalysis.OutputKind.DynamicallyLinkedLibrary));

        using var stream = new MemoryStream();
        var result = compilation.Emit(stream);
        if (!result.Success)
        {
            var errors = string.Join(Environment.NewLine, result.Diagnostics.Select(d => d.ToString()));
            throw new InvalidOperationException($"WIP system compilation failed:{Environment.NewLine}{errors}");
        }

        var context = new AssemblyLoadContext("wip-system", isCollectible: false);
        context.Resolving += (_, name) =>
            name.Name == typeof(ISystemDefinition).Assembly.GetName().Name
                ? typeof(ISystemDefinition).Assembly
                : null;
        stream.Position = 0;
        return context.LoadFromStream(stream);
    }
}

using Intropy.Topology;

namespace Intropy.Topology.WipSystem;

public sealed record WipOrder(string OrderNumber);

/// <summary>
/// A work-in-progress system: the connector keeps the placeholder default transport and the
/// published topic has no subscriber yet. Validation warns on both; the system must still
/// materialize for read-only inspection.
/// </summary>
public sealed class WipSystemDefinition : ISystemDefinition
{
    public static readonly TopicRef<WipOrder> Raw = TopicRef<WipOrder>.Define("pubsub-a", "wip-raw");
    public static readonly ConnectorRef Placeholder = ConnectorRef.Define("placeholder", Transport.Default());

    public string SystemName => "wip-system";

    public void Define(SystemBuilder builder)
    {
        builder.AddExtractor("wip-extractor").From(Placeholder).Publishes(Raw);
    }
}

/// <summary>The local file resolution backing <see cref="WipSystemDefinition"/>'s connector.</summary>
public sealed class WipDevelopment : IDevelopmentDefinition
{
    public void Define(DevelopmentBuilder development)
    {
        development.Files(WipSystemDefinition.Placeholder).RootPath("./test/placeholder");
    }
}

using System.Reflection;

namespace Intropy.Topology.Generation.Test;

/// <summary>
/// A work-in-progress system assembly — placeholder transport, one-sided topic — built
/// from test/Intropy.Topology.WipSystem on first use. Kept out of the solution so its
/// ISystemDefinition never interferes with discovery in the real test assemblies.
/// </summary>
internal static class WipSystemFixture
{
    private static readonly Lazy<Assembly> s_assembly = new(Build, LazyThreadSafetyMode.ExecutionAndPublication);

    public static Assembly Assembly => s_assembly.Value;

    private static Assembly Build()
    {
        var projectDir = Path.GetFullPath(Path.Combine(
            AppContext.BaseDirectory, "..", "..", "..", "..", "Intropy.Topology.WipSystem"));
        var build = System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
        {
            FileName = "dotnet",
            ArgumentList = { "build", projectDir, "-c", "Debug", "--nologo", "-v", "q" },
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        })!;
        build.WaitForExit();
        if (build.ExitCode != 0)
        {
            throw new InvalidOperationException(
                $"WIP system fixture build failed:{Environment.NewLine}{build.StandardOutput.ReadToEnd()}{build.StandardError.ReadToEnd()}");
        }

        return System.Runtime.Loader.AssemblyLoadContext.Default.LoadFromAssemblyPath(
            Path.Combine(projectDir, "bin", "Debug", "net10.0", "Intropy.Topology.WipSystem.dll"));
    }
}

